import { ChangeEvent, FormEvent, ReactNode, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Activity, ArrowUpRight, CalendarDays, Check, ChevronRight, CircleDollarSign, Clock3, FileText, ImagePlus, LayoutDashboard, LogOut, Menu, MessageSquare, Package, Pencil, Plus, RefreshCw, Search, Settings2, ShoppingBag, SlidersHorizontal, Sparkles, Trash2, UploadCloud, Users, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { adminFetch, adminLogout, getAdminMe } from "@/lib/adminAuth";

type AdminStats = { totalUsers: number; totalProducts: number; totalOrders: number; totalAppointments: number; totalSalonBookings: number; totalRevenue: number; pendingOrders: number; lowStockProducts: number };
type Product = { id: string; sku: string; name: string; description: string | null; price_ngn: number; category: string | null; product_type: string | null; image_url: string | null; stock_quantity: number; is_active: boolean; shipping_weight_grams?: number | null; shipping_length_cm?: number | null; shipping_width_cm?: number | null; shipping_height_cm?: number | null; customs_description?: string | null; hs_code?: string | null; country_of_origin?: string | null; ingredients?: string[]; suitable_for_conditions?: string[]; suitable_hair_types?: string[]; suitable_hair_concerns?: string[]; contraindications?: string[]; updated_at?: string; created_at?: string };
type Order = { id: string; user_email: string | null; customer_name: string | null; total_amount_ngn: number; status: string; payment_status: string; created_at: string; items: Array<{ id: string; quantity: number; price_at_purchase: number; product_name: string }> };
type Appointment = { id: string; patient_name: string | null; patient_email: string | null; clinician_name: string | null; scheduled_at: string; status: string };
type SalonBooking = { id: number; customer_name: string; customer_email: string | null; service_name: string; appointment_date: string; time_slot: string; price_ngn: number; status: string; payment_status: string };
type User = { id: string; email: string; full_name: string | null; phone: string | null; location: string | null; roles?: string[]; onboarding_completed?: boolean; created_at: string };
type CommunityPost = { id: string; community_type: string; author_name: string; author_role: string; content: string; image_url: string | null; created_at: string; comment_count: number; reaction_count: number };
type Section = "overview" | "shop" | "orders" | "appointments" | "customers" | "community" | "settings";
type Draft = { sku: string; name: string; description: string; price_ngn: string; category: string; product_type: string; image_url: string; stock_quantity: string; is_active: boolean; shipping_weight_grams: string; shipping_length_cm: string; shipping_width_cm: string; shipping_height_cm: string; customs_description: string; hs_code: string; country_of_origin: string; ingredients: string; suitable_for_conditions: string; suitable_hair_types: string; suitable_hair_concerns: string; contraindications: string };

const freshDraft = (): Draft => ({ sku: "", name: "", description: "", price_ngn: "", category: "", product_type: "hair", image_url: "", stock_quantity: "0", is_active: true, shipping_weight_grams: "", shipping_length_cm: "", shipping_width_cm: "", shipping_height_cm: "", customs_description: "", hs_code: "", country_of_origin: "Nigeria", ingredients: "", suitable_for_conditions: "", suitable_hair_types: "", suitable_hair_concerns: "", contraindications: "" });
const money = (value: number) => `₦${Number(value || 0).toLocaleString("en-NG", { maximumFractionDigits: 0 })}`;
const dateTime = (value?: string) => value ? new Date(value).toLocaleString("en-NG", { dateStyle: "medium", timeStyle: "short" }) : "—";
const splitList = (value: string) => value.split(",").map((item) => item.trim()).filter(Boolean);

async function fileToBase64(file: File) {
  const bytes = new Uint8Array(await file.arrayBuffer());
  let binary = "";
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
  }
  return btoa(binary);
}

function imageContentType(file: File) {
  if (file.type) return file.type.toLowerCase();
  const extension = file.name.toLowerCase().split(".").pop();
  return extension === "jpg" || extension === "jpeg"
    ? "image/jpeg"
    : extension === "png"
      ? "image/png"
      : extension === "webp"
        ? "image/webp"
        : "";
}

const navItems: Array<{ id: Section; label: string; icon: typeof LayoutDashboard; note?: string }> = [
  { id: "overview", label: "Overview", icon: LayoutDashboard },
  { id: "shop", label: "Shop & catalogue", icon: Package, note: "Merchandise" },
  { id: "orders", label: "Orders", icon: ShoppingBag },
  { id: "appointments", label: "Appointments", icon: CalendarDays },
  { id: "customers", label: "Customers", icon: Users },
  { id: "community", label: "Community", icon: MessageSquare },
  { id: "settings", label: "Workspace settings", icon: Settings2 },
];

export default function AdminDashboard() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [section, setSection] = useState<Section>("overview");
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [adminEmail, setAdminEmail] = useState("");
  const [stats, setStats] = useState<AdminStats>({ totalUsers: 0, totalProducts: 0, totalOrders: 0, totalAppointments: 0, totalSalonBookings: 0, totalRevenue: 0, pendingOrders: 0, lowStockProducts: 0 });
  const [products, setProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [salonBookings, setSalonBookings] = useState<SalonBooking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [communityPosts, setCommunityPosts] = useState<CommunityPost[]>([]);
  const [productSearch, setProductSearch] = useState("");
  const [productStatus, setProductStatus] = useState("all");
  const [productCategory, setProductCategory] = useState("all");
  const [productModalOpen, setProductModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [draft, setDraft] = useState<Draft>(freshDraft);
  const [savingProduct, setSavingProduct] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);

  const activeProducts = useMemo(() => products.filter((product) => product.is_active), [products]);
  const categories = useMemo(() => Array.from(new Set(products.map((product) => product.category).filter(Boolean) as string[])).sort(), [products]);
  const lowStockProducts = useMemo(() => products.filter((product) => product.is_active && Number(product.stock_quantity) <= 10), [products]);

  useEffect(() => { initialize(); }, []);
  useEffect(() => { if (editingProduct) setDraft({ sku: editingProduct.sku || "", name: editingProduct.name || "", description: editingProduct.description || "", price_ngn: String(editingProduct.price_ngn ?? ""), category: editingProduct.category || "", product_type: editingProduct.product_type || "hair", image_url: editingProduct.image_url || "", stock_quantity: String(editingProduct.stock_quantity ?? 0), is_active: editingProduct.is_active, shipping_weight_grams: String(editingProduct.shipping_weight_grams ?? ""), shipping_length_cm: String(editingProduct.shipping_length_cm ?? ""), shipping_width_cm: String(editingProduct.shipping_width_cm ?? ""), shipping_height_cm: String(editingProduct.shipping_height_cm ?? ""), customs_description: editingProduct.customs_description || "", hs_code: editingProduct.hs_code || "", country_of_origin: editingProduct.country_of_origin || "Nigeria", ingredients: editingProduct.ingredients?.join(", ") || "", suitable_for_conditions: editingProduct.suitable_for_conditions?.join(", ") || "", suitable_hair_types: editingProduct.suitable_hair_types?.join(", ") || "", suitable_hair_concerns: editingProduct.suitable_hair_concerns?.join(", ") || "", contraindications: editingProduct.contraindications?.join(", ") || "" }); else setDraft(freshDraft()); }, [editingProduct]);

  async function initialize() {
    try { const me = await getAdminMe(); setAdminEmail(me.admin.email); await loadData(); } catch { adminLogout(); navigate("/admin/login"); }
  }

  async function loadData() {
    setRefreshing(true);
    const requests = await Promise.allSettled([adminFetch("/admin/overview"), adminFetch(`/admin/products?search=${encodeURIComponent(productSearch)}&status=${productStatus}&category=${productCategory}`), adminFetch("/admin/orders"), adminFetch("/admin/appointments"), adminFetch("/admin/salon-bookings"), adminFetch("/admin/users"), adminFetch("/admin/community/posts")]);
    const [overview, productData, ordersData, appointmentData, salonData, usersData, communityData] = requests;
    if (overview.status === "fulfilled") setStats(overview.value.stats);
    if (productData.status === "fulfilled") setProducts(productData.value);
    if (ordersData.status === "fulfilled") setOrders(ordersData.value);
    if (appointmentData.status === "fulfilled") setAppointments(appointmentData.value);
    if (salonData.status === "fulfilled") setSalonBookings(salonData.value);
    if (usersData.status === "fulfilled") setUsers(usersData.value);
    if (communityData.status === "fulfilled") setCommunityPosts(communityData.value);
    if (overview.status === "rejected" || productData.status === "rejected") toast({ title: "Control room data needs attention", description: "The catalogue or overview could not be loaded. Please check the API connection.", variant: "destructive" });
    setLoading(false); setRefreshing(false);
  }

  function goTo(next: Section) { setSection(next); setMobileNavOpen(false); }
  function logout() { adminLogout(); navigate("/admin/login"); }
  function openNewProduct() { setEditingProduct(null); setProductModalOpen(true); }
  function openEditProduct(product: Product) { setEditingProduct(product); setProductModalOpen(true); }
  function setField(field: keyof Draft, value: string | boolean) { setDraft((current) => ({ ...current, [field]: value })); }

  async function uploadProductImage(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;
    const contentType = imageContentType(file);
    if (!contentType || !["image/jpeg", "image/png", "image/webp"].includes(contentType)) {
      toast({ title: "Image upload failed", description: "Use a JPEG, PNG, or WebP image under 8MB.", variant: "destructive" });
      event.target.value = "";
      return;
    }
    if (file.size === 0 || file.size > 8 * 1024 * 1024) {
      toast({ title: "Image upload failed", description: "Use a JPEG, PNG, or WebP image under 8MB.", variant: "destructive" });
      event.target.value = "";
      return;
    }
    setUploadingImage(true);
    try {
      const base64 = await fileToBase64(file);
      const result = await adminFetch("/admin/product-image", {
        method: "POST",
        body: JSON.stringify({ fileName: file.name, base64, contentType }),
      });
      setField("image_url", result.url || result.publicUrl);
      toast({ title: "Image uploaded", description: "The product image is ready to publish." });
    } catch (error: any) {
      toast({ title: "Image upload failed", description: error?.message || "Use a JPEG, PNG, or WebP image under 8MB.", variant: "destructive" });
    } finally {
      setUploadingImage(false);
      event.target.value = "";
    }
  }

  async function saveProduct(event: FormEvent) {
    event.preventDefault();
    setSavingProduct(true);
    try {
      const numericOrNull = (value: string) => value.trim() === "" ? null : Number(value); const payload = { sku: draft.sku.trim(), name: draft.name.trim(), description: draft.description.trim() || null, price_ngn: Number(draft.price_ngn), category: draft.category.trim() || null, product_type: draft.product_type, image_url: draft.image_url.trim() || null, stock_quantity: Number(draft.stock_quantity), is_active: draft.is_active, shipping_weight_grams: numericOrNull(draft.shipping_weight_grams), shipping_length_cm: numericOrNull(draft.shipping_length_cm), shipping_width_cm: numericOrNull(draft.shipping_width_cm), shipping_height_cm: numericOrNull(draft.shipping_height_cm), customs_description: draft.customs_description.trim() || null, hs_code: draft.hs_code.trim() || null, country_of_origin: draft.country_of_origin.trim() || null, ingredients: splitList(draft.ingredients), suitable_for_conditions: splitList(draft.suitable_for_conditions), suitable_hair_types: splitList(draft.suitable_hair_types), suitable_hair_concerns: splitList(draft.suitable_hair_concerns), contraindications: splitList(draft.contraindications) };
      const path = editingProduct ? `/admin/products/${editingProduct.id}` : "/admin/products";
      await adminFetch(path, { method: editingProduct ? "PUT" : "POST", body: JSON.stringify(payload) });
      toast({ title: editingProduct ? "Product updated" : "Product published", description: `${payload.name} is now in your catalogue.` });
      setProductModalOpen(false); setEditingProduct(null); await loadData();
    } catch (error: any) { toast({ title: "Could not save product", description: error?.message || "Check the product details and try again.", variant: "destructive" }); }
    finally { setSavingProduct(false); }
  }

  async function deleteProduct(product: Product) {
    if (!window.confirm(`Remove ${product.name} from the catalogue?`)) return;
    try { await adminFetch(`/admin/products/${product.id}`, { method: "DELETE" }); toast({ title: "Product removed", description: `${product.name} has been removed from the catalogue.` }); await loadData(); }
    catch (error: any) { toast({ title: "Could not remove product", description: error?.message || "Please try again.", variant: "destructive" }); }
  }

  async function updateStatus(path: string, payload: Record<string, string>, success: string) {
    try { await adminFetch(path, { method: "PUT", body: JSON.stringify(payload) }); toast({ title: "Saved", description: success }); await loadData(); }
    catch (error: any) { toast({ title: "Update failed", description: error?.message || "Please try again.", variant: "destructive" }); }
  }

  async function deleteCommunityPost(post: CommunityPost) {
    if (!window.confirm(`Remove this ${post.community_type} community post?`)) return;
    try { await adminFetch(`/admin/community/posts/${post.id}`, { method: "DELETE" }); toast({ title: "Post removed", description: "The community post is no longer visible." }); await loadData(); }
    catch (error: any) { toast({ title: "Could not remove post", description: error?.message || "Please try again.", variant: "destructive" }); }
  }

  if (loading) return <div className="flex min-h-screen items-center justify-center bg-[#f7f3ee] text-[#5e493a]"><div className="text-center"><div className="mx-auto mb-4 h-10 w-10 animate-spin rounded-full border-2 border-[#d8c3ae] border-t-[#70452c]" /><p className="text-sm">Preparing your control room…</p></div></div>;

  return <div className="min-h-screen bg-[#f7f3ee] text-[#2d211b]">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[278px] flex-col border-r border-[#eadfd3] bg-[#211712] text-white transition-transform duration-200 lg:translate-x-0 ${mobileNavOpen ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-24 items-center justify-between border-b border-white/10 px-7"><div><p className="text-[10px] font-semibold uppercase tracking-[0.32em] text-[#d7ad78]">IMSTEV NATURALS</p><p className="mt-2 text-sm text-[#c1b0a0]">Operations studio</p></div><button className="text-[#cbb9a8] lg:hidden" onClick={() => setMobileNavOpen(false)} aria-label="Close navigation"><X className="h-5 w-5" /></button></div>
      <nav className="flex-1 space-y-1 px-4 py-6">{navItems.map(({ id, label, icon: Icon, note }) => <button key={id} onClick={() => goTo(id)} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition ${section === id ? "bg-[#a26b43] text-white shadow-lg shadow-black/10" : "text-[#c6b7a9] hover:bg-white/5 hover:text-white"}`}><Icon className="h-[18px] w-[18px]" /><span className="flex-1">{label}</span>{note && section !== id ? <span className="text-[9px] uppercase tracking-wider text-[#a89483]">{note}</span> : null}<ChevronRight className={`h-4 w-4 transition ${section === id ? "opacity-100" : "opacity-0 group-hover:opacity-70"}`} /></button>)}</nav>
      <div className="border-t border-white/10 p-4"><div className="rounded-2xl bg-white/5 p-4"><p className="text-xs uppercase tracking-[0.18em] text-[#a89483]">Signed in as</p><p className="mt-2 truncate text-sm font-medium text-[#f5eee6]">{adminEmail}</p><button onClick={logout} className="mt-4 flex items-center gap-2 text-sm text-[#d7ad78] hover:text-white"><LogOut className="h-4 w-4" /> Sign out</button></div></div>
    </aside>
    {mobileNavOpen ? <button aria-label="Close navigation overlay" onClick={() => setMobileNavOpen(false)} className="fixed inset-0 z-30 bg-black/40 lg:hidden" /> : null}
    <div className="lg:pl-[278px]">
      <header className="sticky top-0 z-20 border-b border-[#eadfd3]/90 bg-[#f7f3ee]/95 px-4 py-4 backdrop-blur sm:px-8 lg:px-10"><div className="flex items-center justify-between gap-4"><div className="flex items-center gap-3"><button className="rounded-lg border border-[#e4d6c8] bg-white p-2 lg:hidden" onClick={() => setMobileNavOpen(true)} aria-label="Open navigation"><Menu className="h-5 w-5" /></button><div><p className="text-xs font-semibold uppercase tracking-[0.2em] text-[#a26b43]">IMSTEV control room</p><h1 className="mt-1 font-display text-2xl tracking-[-0.03em] sm:text-3xl">{navItems.find((item) => item.id === section)?.label}</h1></div></div><div className="flex items-center gap-2 sm:gap-3"><Button variant="outline" onClick={() => loadData()} disabled={refreshing} className="h-10 border-[#e1d2c3] bg-white text-[#614734]">{refreshing ? <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-[#d5c0ae] border-t-[#70452c]" /> : <RefreshCw className="mr-2 h-4 w-4" />}<span className="hidden sm:inline">Refresh</span></Button><Button onClick={() => goTo("shop")} className="h-10 bg-[#70452c] text-white hover:bg-[#593620]"><Plus className="mr-2 h-4 w-4" /><span className="hidden sm:inline">New product</span><span className="sm:hidden">Add</span></Button></div></div></header>
      <main className="mx-auto max-w-[1500px] px-4 py-7 sm:px-8 lg:px-10 lg:py-9">{section === "overview" ? <Overview stats={stats} products={products} lowStockProducts={lowStockProducts} orders={orders} appointments={appointments} onGo={goTo} /> : null}{section === "shop" ? <Shop products={products} activeProducts={activeProducts} categories={categories} search={productSearch} status={productStatus} category={productCategory} onSearch={setProductSearch} onStatus={setProductStatus} onCategory={setProductCategory} onFilter={loadData} onNew={openNewProduct} onEdit={openEditProduct} onDelete={deleteProduct} onRefresh={loadData} /> : null}{section === "orders" ? <Orders orders={orders} onUpdate={updateStatus} /> : null}{section === "appointments" ? <Appointments appointments={appointments} salonBookings={salonBookings} onUpdate={updateStatus} /> : null}{section === "customers" ? <Customers users={users} /> : null}{section === "community" ? <Community posts={communityPosts} onDelete={deleteCommunityPost} /> : null}{section === "settings" ? <Settings adminEmail={adminEmail} /> : null}</main>
    </div>
    {productModalOpen ? <ProductModal draft={draft} editing={editingProduct} saving={savingProduct} uploading={uploadingImage} onChange={setField} onUpload={uploadProductImage} onSubmit={saveProduct} onClose={() => { setProductModalOpen(false); setEditingProduct(null); }} /> : null}
  </div>;
}

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-xs font-semibold uppercase tracking-[0.22em] text-[#a26b43]">{eyebrow}</p><h2 className="mt-2 font-display text-3xl tracking-[-0.04em] sm:text-4xl">{title}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#806f60]">{description}</p></div>{action}</div>; }
function Metric({ label, value, detail, icon: Icon, tone = "light" }: { label: string; value: string | number; detail: string; icon: typeof Activity; tone?: "light" | "dark" }) { return <div className={`rounded-2xl border p-5 ${tone === "dark" ? "border-[#38271d] bg-[#2b1e17] text-white" : "border-[#eadfd3] bg-white"}`}><div className="flex items-start justify-between"><p className={`text-xs font-semibold uppercase tracking-[0.16em] ${tone === "dark" ? "text-[#d7ad78]" : "text-[#987e69]"}`}>{label}</p><span className={`rounded-xl p-2 ${tone === "dark" ? "bg-white/10 text-[#e6c499]" : "bg-[#f6eee6] text-[#9b6846]"}`}><Icon className="h-4 w-4" /></span></div><p className={`mt-5 font-display text-3xl ${tone === "dark" ? "text-white" : "text-[#2d211b]"}`}>{value}</p><p className={`mt-2 text-xs ${tone === "dark" ? "text-[#bfac9b]" : "text-[#897666]"}`}>{detail}</p></div>; }
function Panel({ title, subtitle, children, action }: { title: string; subtitle?: string; children: ReactNode; action?: ReactNode }) { return <section className="rounded-2xl border border-[#eadfd3] bg-white p-5 shadow-[0_12px_40px_rgba(67,40,22,0.04)] sm:p-6"><div className="mb-5 flex items-start justify-between gap-4"><div><h3 className="font-display text-xl tracking-[-0.02em]">{title}</h3>{subtitle ? <p className="mt-1 text-sm text-[#897666]">{subtitle}</p> : null}</div>{action}</div>{children}</section>; }

function Overview({ stats, products, lowStockProducts, orders, appointments, onGo }: { stats: AdminStats; products: Product[]; lowStockProducts: Product[]; orders: Order[]; appointments: Appointment[]; onGo: (section: Section) => void }) { return <><PageIntro eyebrow="Good morning, Stephen" title="A clear view of the work." description="The essential rhythm of your shop, studio, and community — ready for the next thoughtful decision." action={<button onClick={() => onGo("shop")} className="inline-flex items-center gap-2 text-sm font-semibold text-[#70452c] hover:text-[#a26b43]">Curate the catalogue <ArrowUpRight className="h-4 w-4" /></button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Net sales" value={money(stats.totalRevenue)} detail="Verified store revenue" icon={CircleDollarSign} tone="dark" /><Metric label="Catalogue" value={stats.totalProducts} detail={`${products.filter((product) => product.is_active).length} active products`} icon={Package} /><Metric label="Customers" value={stats.totalUsers} detail="Registered accounts" icon={Users} /><Metric label="Bookings" value={stats.totalSalonBookings + stats.totalAppointments} detail="Salon and consultation visits" icon={CalendarDays} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_0.7fr]"><Panel title="Attention this week" subtitle="A considered queue for the next few actions"><div className="grid gap-3 sm:grid-cols-3"><button onClick={() => onGo("shop")} className="rounded-2xl bg-[#fbf5ed] p-4 text-left transition hover:-translate-y-0.5"><div className="flex items-center justify-between"><Package className="h-5 w-5 text-[#a26b43]" /><span className="font-display text-2xl">{lowStockProducts.length}</span></div><p className="mt-8 text-sm font-semibold">Low-stock products</p><p className="mt-1 text-xs leading-5 text-[#897666]">Review before the next order cycle.</p></button><button onClick={() => onGo("orders")} className="rounded-2xl bg-[#f4f0ea] p-4 text-left transition hover:-translate-y-0.5"><div className="flex items-center justify-between"><ShoppingBag className="h-5 w-5 text-[#a26b43]" /><span className="font-display text-2xl">{stats.pendingOrders}</span></div><p className="mt-8 text-sm font-semibold">Orders to move</p><p className="mt-1 text-xs leading-5 text-[#897666]">Confirm, pack, and keep customers close.</p></button><button onClick={() => onGo("appointments")} className="rounded-2xl bg-[#f7eee9] p-4 text-left transition hover:-translate-y-0.5"><div className="flex items-center justify-between"><Clock3 className="h-5 w-5 text-[#a26b43]" /><span className="font-display text-2xl">{appointments.length}</span></div><p className="mt-8 text-sm font-semibold">Consultation queue</p><p className="mt-1 text-xs leading-5 text-[#897666]">Keep the human hand in every handoff.</p></button></div></Panel><Panel title="Recent orders" subtitle="The latest movement in your shop" action={<button onClick={() => onGo("orders")} className="text-sm font-semibold text-[#70452c]">View all</button>}><div className="space-y-3">{orders.length ? orders.slice(0, 5).map((order) => <div key={order.id} className="flex items-center justify-between gap-4 border-b border-[#f0e8df] pb-3 last:border-0 last:pb-0"><div className="min-w-0"><p className="truncate text-sm font-semibold">{order.customer_name || order.user_email || "Customer"}</p><p className="mt-1 text-xs text-[#897666]">{dateTime(order.created_at)}</p></div><div className="text-right"><p className="text-sm font-semibold">{money(order.total_amount_ngn)}</p><StatusBadge value={order.status} /></div></div>) : <EmptyState icon={ShoppingBag} title="No orders yet" text="Verified store orders will appear here." />}</div></Panel></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Panel title="Catalogue pulse" subtitle="Your strongest operational signal"><div className="space-y-4"><ProgressRow label="Active catalogue" value={products.length ? Math.round((products.filter((product) => product.is_active).length / products.length) * 100) : 0} detail={`${products.filter((product) => product.is_active).length} of ${products.length} products live`} /><ProgressRow label="Healthy stock cover" value={products.length ? Math.round(((products.length - lowStockProducts.length) / products.length) * 100) : 0} detail={`${products.length - lowStockProducts.length} products above threshold`} /><ProgressRow label="Order movement" value={stats.totalOrders ? Math.min(100, Math.round(((stats.totalOrders - stats.pendingOrders) / stats.totalOrders) * 100)) : 0} detail={`${stats.totalOrders - stats.pendingOrders} orders moved forward`} /></div></Panel><Panel title="Studio principle" subtitle="A reminder for the team"><blockquote className="border-l-2 border-[#c79461] pl-5 font-display text-2xl leading-tight text-[#5f432f]">“Every detail should feel like it was chosen by a person who cares.”</blockquote><p className="mt-5 text-sm leading-6 text-[#897666]">Use the control room to keep the storefront precise, the service calendar calm, and the community worthy of the people inside it.</p></Panel></div></>; }
function ProgressRow({ label, value, detail }: { label: string; value: number; detail: string }) { return <div><div className="flex items-center justify-between text-sm"><span className="font-medium">{label}</span><span className="text-[#a26b43]">{value}%</span></div><div className="mt-2 h-2 rounded-full bg-[#f0e7dd]"><div className="h-2 rounded-full bg-[#a26b43] transition-all" style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div><p className="mt-2 text-xs text-[#897666]">{detail}</p></div>; }

function Shop({ products, activeProducts, categories, search, status, category, onSearch, onStatus, onCategory, onFilter, onNew, onEdit, onDelete }: { products: Product[]; activeProducts: Product[]; categories: string[]; search: string; status: string; category: string; onSearch: (value: string) => void; onStatus: (value: string) => void; onCategory: (value: string) => void; onFilter: () => void; onNew: () => void; onEdit: (product: Product) => void; onDelete: (product: Product) => void; onRefresh: () => void }) { return <><PageIntro eyebrow="Merchandise studio" title="Make the catalogue feel considered." description="Upload the visual, sharpen the story, set the price, and keep every product ready for the people it serves." action={<Button onClick={onNew} className="bg-[#70452c] text-white hover:bg-[#593620]"><Plus className="mr-2 h-4 w-4" /> Add product</Button>} /><div className="mb-6 grid gap-3 sm:grid-cols-3"><Metric label="Live products" value={activeProducts.length} detail="Visible on the public shop" icon={Package} /><Metric label="All products" value={products.length} detail="Including paused listings" icon={SlidersHorizontal} /><Metric label="Categories" value={categories.length} detail="Distinct catalogue groups" icon={Activity} /></div><Panel title="Catalogue" subtitle="Search, filter, and edit your shop in one place"><div className="mb-6 flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#a28d7c]" /><Input value={search} onChange={(event) => onSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") onFilter(); }} placeholder="Search by product name, SKU, or category" className="h-11 border-[#e6d8ca] pl-10" /></div><select value={status} onChange={(event) => onStatus(event.target.value)} className="h-11 rounded-md border border-[#e6d8ca] bg-white px-3 text-sm"><option value="all">All statuses</option><option value="active">Live only</option><option value="inactive">Paused only</option></select><select value={category} onChange={(event) => onCategory(event.target.value)} className="h-11 rounded-md border border-[#e6d8ca] bg-white px-3 text-sm"><option value="all">All categories</option>{categories.map((item) => <option key={item} value={item}>{item}</option>)}</select><Button onClick={onFilter} variant="outline" className="h-11 border-[#e1d2c3]">Apply</Button></div>{products.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{products.map((product) => <ProductCard key={product.id} product={product} onEdit={onEdit} onDelete={onDelete} />)}</div> : <EmptyState icon={Package} title="Your catalogue is ready for its first story" text="Add a product with its image, price, and care guidance to make it live on the shop." action={<Button onClick={onNew} className="bg-[#70452c] text-white">Add your first product</Button>} />}</Panel></>; }
function ProductCard({ product, onEdit, onDelete }: { product: Product; onEdit: (product: Product) => void; onDelete: (product: Product) => void }) { return <article className="group overflow-hidden rounded-2xl border border-[#eadfd3] bg-[#fffdfb] transition hover:-translate-y-0.5 hover:shadow-[0_18px_45px_rgba(67,40,22,0.10)]"><div className="relative aspect-[1.15] overflow-hidden bg-[#f1e9df]">{product.image_url ? <img src={product.image_url} alt={product.name} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" /> : <div className="flex h-full flex-col items-center justify-center gap-3 text-[#ad967f]"><ImagePlus className="h-8 w-8" /><span className="text-xs uppercase tracking-[0.18em]">No image yet</span></div>}<div className="absolute left-3 top-3"><StatusBadge value={product.is_active ? "Live" : "Paused"} /></div><div className="absolute right-3 top-3 rounded-full bg-white/90 px-2.5 py-1 text-xs font-semibold text-[#66452f]">{money(product.price_ngn)}</div></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#a26b43]">{product.category || product.product_type || "Catalogue"}</p><h3 className="mt-1 font-display text-xl leading-tight">{product.name}</h3></div><span className="text-xs text-[#897666]">{product.stock_quantity} in stock</span></div><p className="mt-3 line-clamp-2 min-h-10 text-sm leading-5 text-[#806f60]">{product.description || "No description added yet."}</p><div className="mt-5 flex items-center justify-between border-t border-[#f0e8df] pt-4"><span className="font-mono text-[11px] text-[#a28d7c]">{product.sku || "NO SKU"}</span><div className="flex gap-2"><button onClick={() => onEdit(product)} className="rounded-lg border border-[#e5d8ca] p-2 text-[#70452c] hover:bg-[#fbf5ed]" aria-label={`Edit ${product.name}`}><Pencil className="h-4 w-4" /></button><button onClick={() => onDelete(product)} className="rounded-lg border border-[#ecd9d5] p-2 text-[#a35e51] hover:bg-[#fff6f3]" aria-label={`Delete ${product.name}`}><Trash2 className="h-4 w-4" /></button></div></div></div></article>; }

function Orders({ orders, onUpdate }: { orders: Order[]; onUpdate: (path: string, payload: Record<string, string>, success: string) => void }) { return <><PageIntro eyebrow="Store operations" title="Keep every order moving." description="Payment status, fulfilment rhythm, and customer confidence in one queue." /><Panel title="Order queue" subtitle={`${orders.length} order${orders.length === 1 ? "" : "s"} in the system`}>{orders.length ? <div className="space-y-4">{orders.map((order) => <div key={order.id} className="rounded-2xl border border-[#eee5dc] p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-start"><div><div className="flex flex-wrap items-center gap-2"><h3 className="font-semibold">{order.customer_name || order.user_email || "Customer"}</h3><StatusBadge value={order.status} /></div><p className="mt-2 text-sm text-[#897666]">{dateTime(order.created_at)} · {order.items?.length || 0} line items</p></div><p className="font-display text-2xl">{money(order.total_amount_ngn)}</p></div><div className="mt-5 flex flex-col gap-3 border-t border-[#f0e8df] pt-4 sm:flex-row sm:items-center sm:justify-between"><div className="space-y-1 text-sm text-[#806f60]">{(order.items || []).slice(0, 3).map((item) => <p key={item.id}>{item.quantity} × {item.product_name} <span className="text-[#aa8e78">({money(item.price_at_purchase)})</span></p>)}</div><div className="flex gap-2"><select value={order.status} onChange={(event) => onUpdate(`/admin/orders/${order.id}`, { status: event.target.value }, "Order status updated.")} className="h-10 rounded-md border border-[#e6d8ca] bg-white px-3 text-sm"><option value="pending">Pending</option><option value="processing">Processing</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><select value={order.payment_status || "pending"} onChange={(event) => onUpdate(`/admin/orders/${order.id}`, { payment_status: event.target.value }, "Payment status updated.")} className="h-10 rounded-md border border-[#e6d8ca] bg-white px-3 text-sm"><option value="pending">Payment pending</option><option value="paid">Paid</option><option value="failed">Failed</option></select></div></div></div>)}</div> : <EmptyState icon={ShoppingBag} title="No orders to review" text="Verified store purchases will appear in this operational queue." />}</Panel></>; }

function Appointments({ appointments, salonBookings, onUpdate }: { appointments: Appointment[]; salonBookings: SalonBooking[]; onUpdate: (path: string, payload: Record<string, string>, success: string) => void }) { return <><PageIntro eyebrow="Care calendar" title="Protect the pace of the studio." description="Keep consultations and in-salon visits visible, confirmed, and human." /><div className="grid gap-6 xl:grid-cols-2"><Panel title="Salon bookings" subtitle={`${salonBookings.length} visit${salonBookings.length === 1 ? "" : "s"} on the calendar`}>{salonBookings.length ? <div className="space-y-3">{salonBookings.map((booking) => <div key={booking.id} className="rounded-2xl border border-[#eee5dc] p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{booking.customer_name}</p><p className="mt-1 text-sm text-[#806f60]">{booking.service_name}</p><p className="mt-2 text-xs text-[#a28d7c]">{booking.appointment_date} · {booking.time_slot}</p></div><p className="font-semibold">{money(booking.price_ngn)}</p></div><div className="mt-4 flex items-center justify-between gap-3"><StatusBadge value={booking.payment_status} /><select value={booking.status} onChange={(event) => onUpdate(`/admin/salon-bookings/${booking.id}`, { status: event.target.value }, "Salon booking updated.")} className="h-9 rounded-md border border-[#e6d8ca] bg-white px-2 text-xs"><option value="confirmed">Confirmed</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option><option value="no-show">No-show</option></select></div></div>)}</div> : <EmptyState icon={CalendarDays} title="No salon visits yet" text="Bookings will land here as customers choose their care experience." />}</Panel><Panel title="Consultations" subtitle={`${appointments.length} telehealth appointment${appointments.length === 1 ? "" : "s"}`}>{appointments.length ? <div className="space-y-3">{appointments.map((appointment) => <div key={appointment.id} className="rounded-2xl border border-[#eee5dc] p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{appointment.patient_name || appointment.patient_email || "Patient"}</p><p className="mt-1 text-sm text-[#806f60]">{appointment.clinician_name || "Specialist"}</p><p className="mt-2 text-xs text-[#a28d7c]">{dateTime(appointment.scheduled_at)}</p></div><StatusBadge value={appointment.status} /></div><select value={appointment.status} onChange={(event) => onUpdate(`/admin/appointments/${appointment.id}`, { status: event.target.value }, "Consultation status updated.")} className="mt-4 h-9 rounded-md border border-[#e6d8ca] bg-white px-2 text-xs"><option value="scheduled">Scheduled</option><option value="confirmed">Confirmed</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>)}</div> : <EmptyState icon={Activity} title="No consultation queue" text="Telehealth activity will appear here when configured." />}</Panel></div></>; }

function Customers({ users }: { users: User[] }) { return <><PageIntro eyebrow="Customer care" title="Know who you are caring for." description="A clear, respectful view of customers and their relationship with the brand." /><Panel title="Customer directory" subtitle={`${users.length} registered account${users.length === 1 ? "" : "s"}`}><div className="overflow-x-auto">{users.length ? <table className="w-full min-w-[680px] text-left text-sm"><thead className="border-b border-[#eee5dc] text-xs uppercase tracking-[0.14em] text-[#a28d7c]"><tr><th className="pb-3 font-medium">Customer</th><th className="pb-3 font-medium">Contact</th><th className="pb-3 font-medium">Profile</th><th className="pb-3 font-medium">Joined</th></tr></thead><tbody>{users.map((user) => <tr key={user.id} className="border-b border-[#f2ebe4] last:border-0"><td className="py-4"><p className="font-semibold">{user.full_name || "Unnamed customer"}</p><p className="mt-1 text-xs text-[#a28d7c]">{user.roles?.join(" · ") || "Customer"}</p></td><td className="py-4"><p>{user.email}</p><p className="mt-1 text-xs text-[#897666]">{user.phone || "No phone added"}</p></td><td className="py-4"><StatusBadge value={user.onboarding_completed ? "Profile complete" : "Profile to finish"} /></td><td className="py-4 text-[#806f60]">{new Date(user.created_at).toLocaleDateString("en-NG")}</td></tr>)}</tbody></table> : <EmptyState icon={Users} title="No customers to show" text="Customer profiles will appear here as the community grows." />}</div></Panel></>; }

function Community({ posts, onDelete }: { posts: CommunityPost[]; onDelete: (post: CommunityPost) => void }) { return <><PageIntro eyebrow="Community stewardship" title="Hold the tone of the room." description="Review what members share, keep the conversation generous, and protect the standard of the IMSTEV care circle." /><div className="mb-6 grid gap-4 sm:grid-cols-3"><Metric label="Published posts" value={posts.length} detail="Visible in the community feed" icon={MessageSquare} /><Metric label="Reactions" value={posts.reduce((sum, post) => sum + Number(post.reaction_count || 0), 0)} detail="Likes and loves from members" icon={Activity} /><Metric label="Conversations" value={posts.reduce((sum, post) => sum + Number(post.comment_count || 0), 0)} detail="Comments to keep an eye on" icon={Users} /></div><Panel title="Post review" subtitle="Remove only what does not protect the room.">{posts.length ? <div className="grid gap-4 lg:grid-cols-2">{posts.map((post) => <article key={post.id} className="overflow-hidden rounded-2xl border border-[#eee5dc] bg-[#fffdfb]">{post.image_url ? <img src={post.image_url} alt="" className="h-40 w-full object-cover" /> : null}<div className="p-5"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><StatusBadge value={post.community_type} /><span className="text-xs text-[#a28d7c]">{dateTime(post.created_at)}</span></div><h3 className="mt-3 font-semibold">{post.author_name}</h3><p className="mt-1 text-xs text-[#a28d7c]">{post.author_role}</p></div><button onClick={() => onDelete(post)} className="rounded-lg border border-[#ecd9d5] p-2 text-[#a35e51] hover:bg-[#fff6f3]" aria-label="Remove community post"><Trash2 className="h-4 w-4" /></button></div><p className="mt-4 text-sm leading-6 text-[#806f60]">{post.content}</p><div className="mt-5 flex gap-4 border-t border-[#f0e8df] pt-4 text-xs text-[#897666]"><span>{post.comment_count} comments</span><span>{post.reaction_count} reactions</span></div></div></article>)}</div> : <EmptyState icon={MessageSquare} title="No community posts" text="Published member posts will appear here for thoughtful moderation." />}</Panel></>; }
function Settings({ adminEmail }: { adminEmail: string }) { return <><PageIntro eyebrow="Workspace settings" title="Keep the foundations clear." description="Operational details for the person responsible for the IMSTEV NATURALS standard." /><div className="grid gap-6 lg:grid-cols-2"><Panel title="Administrator profile" subtitle="Current access identity"><div className="flex items-center gap-4 rounded-2xl bg-[#fbf5ed] p-4"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-[#70452c] text-white"><ShieldIcon /></div><div><p className="font-semibold">Primary administrator</p><p className="mt-1 text-sm text-[#806f60]">{adminEmail}</p></div></div><p className="mt-5 text-sm leading-6 text-[#806f60]">For production, keep this account backed by a database credential with a strong secret, rotate access periodically, and never place the password in source control.</p></Panel><Panel title="Commerce controls" subtitle="What the portal manages today"><div className="space-y-3">{[[Package, "Product catalogue", "Names, descriptions, photos, prices, stock, and visibility"], [ShoppingBag, "Orders", "Payment and fulfilment status"], [CalendarDays, "Service calendar", "Salon and telehealth appointments"], [Users, "Customer care", "Customer directory and profile completion"]].map(([Icon, title, detail]) => { const FeatureIcon = Icon as typeof Activity; return <div key={String(title)} className="flex gap-3 rounded-xl border border-[#eee5dc] p-3"><FeatureIcon className="mt-0.5 h-4 w-4 text-[#a26b43]" /><div><p className="text-sm font-semibold">{String(title)}</p><p className="mt-1 text-xs leading-5 text-[#897666]">{String(detail)}</p></div></div>; })}</div></Panel></div></>; }
function ProductModal({ draft, editing, saving, uploading, onChange, onUpload, onSubmit, onClose }: { draft: Draft; editing: Product | null; saving: boolean; uploading: boolean; onChange: (field: keyof Draft, value: string | boolean) => void; onUpload: (event: ChangeEvent<HTMLInputElement>) => void; onSubmit: (event: FormEvent) => void; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/50 p-0 sm:items-center sm:p-5"><div className="max-h-[94vh] w-full max-w-4xl overflow-y-auto rounded-t-3xl bg-[#fffdfb] shadow-2xl sm:rounded-3xl"><div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#eee5dc] bg-[#fffdfb]/95 px-5 py-5 backdrop-blur sm:px-7"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#a26b43]">Catalogue editor</p><h2 className="mt-1 font-display text-2xl">{editing ? "Refine product" : "Create a product"}</h2></div><button onClick={onClose} className="rounded-full border border-[#e5d8ca] p-2 text-[#806f60] hover:bg-[#fbf5ed]" aria-label="Close product editor"><X className="h-5 w-5" /></button></div><form onSubmit={onSubmit} className="grid gap-7 p-5 sm:p-7 lg:grid-cols-[0.82fr_1.18fr]"><div><div className="overflow-hidden rounded-2xl border border-[#eadfd3] bg-[#f4ede5]"><div className="aspect-square">{draft.image_url ? <img src={draft.image_url} alt="Product preview" className="h-full w-full object-cover" /> : <div className="flex h-full flex-col items-center justify-center gap-3 text-[#ad967f]"><ImagePlus className="h-10 w-10" /><p className="text-sm">Add a product image</p></div>}</div></div><label className="mt-4 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-[#c9ae95] bg-[#fbf5ed] px-4 py-3 text-sm font-semibold text-[#70452c] transition hover:bg-[#f6eadc]"><UploadCloud className="h-4 w-4" />{uploading ? "Uploading image…" : "Upload product image"}<input type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={onUpload} disabled={uploading} /></label><p className="mt-3 text-xs leading-5 text-[#897666]">Use a clear JPEG, PNG, or WebP image. Maximum 8MB. The image will appear on the public shop after you publish.</p></div><div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2"><Field label="Product name" value={draft.name} onChange={(value) => onChange("name", value)} required placeholder="e.g. Baobab + Shea Care Oil" /><Field label="SKU" value={draft.sku} onChange={(value) => onChange("sku", value)} placeholder="e.g. IM-HR-001" /></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Price (NGN)" type="number" value={draft.price_ngn} onChange={(value) => onChange("price_ngn", value)} required placeholder="0" /><Field label="Stock quantity" type="number" value={draft.stock_quantity} onChange={(value) => onChange("stock_quantity", value)} placeholder="0" /></div><div className="rounded-2xl border border-[#eadfd3] bg-[#fbf5ed] p-4"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[#a26b43]">Shipping data</p><p className="mt-2 text-xs leading-5 text-[#806f60]">Use the final sealed package measurements. Live shipping will stay unavailable for products without complete packed data.</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Packed weight (grams)" type="number" value={draft.shipping_weight_grams} onChange={(value) => onChange("shipping_weight_grams", value)} placeholder="e.g. 250" /><Field label="Packed length (cm)" type="number" value={draft.shipping_length_cm} onChange={(value) => onChange("shipping_length_cm", value)} placeholder="e.g. 18" /><Field label="Packed width (cm)" type="number" value={draft.shipping_width_cm} onChange={(value) => onChange("shipping_width_cm", value)} placeholder="e.g. 12" /><Field label="Packed height (cm)" type="number" value={draft.shipping_height_cm} onChange={(value) => onChange("shipping_height_cm", value)} placeholder="e.g. 8" /><Field label="HS code" value={draft.hs_code} onChange={(value) => onChange("hs_code", value)} placeholder="Confirm with your customs adviser" /><Field label="Country of origin" value={draft.country_of_origin} onChange={(value) => onChange("country_of_origin", value)} placeholder="Nigeria" /></div><div className="mt-4"><Label>Customs description</Label><Input value={draft.customs_description} onChange={(event) => onChange("customs_description", event.target.value)} placeholder="e.g. Organic hair and skin care oil" className="mt-2 h-11 border-[#e6d8ca]" /></div></div><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Product type" value={draft.product_type} onChange={(value) => onChange("product_type", value)} options={[["hair", "Hair"], ["skin", "Skin"], ["both", "Hair + skin"]]} /><Field label="Category" value={draft.category} onChange={(value) => onChange("category", value)} placeholder="e.g. Oils, Cleansers" /></div><div><Label>Description</Label><Textarea value={draft.description} onChange={(event) => onChange("description", event.target.value)} placeholder="Describe the care experience, texture, use, and who it is for." className="mt-2 min-h-28 border-[#e6d8ca] bg-white" /></div><div className="grid gap-4 sm:grid-cols-2"><TagField label="Ingredients" value={draft.ingredients} onChange={(value) => onChange("ingredients", value)} placeholder="Baobab oil, Shea butter" /><TagField label="Suitable hair types" value={draft.suitable_hair_types} onChange={(value) => onChange("suitable_hair_types", value)} placeholder="4A, 4B, 4C" /><TagField label="Hair concerns" value={draft.suitable_hair_concerns} onChange={(value) => onChange("suitable_hair_concerns", value)} placeholder="Dryness, breakage" /><TagField label="Skin conditions" value={draft.suitable_for_conditions} onChange={(value) => onChange("suitable_for_conditions", value)} placeholder="Dryness, sensitivity" /></div><TagField label="Contraindications" value={draft.contraindications} onChange={(value) => onChange("contraindications", value)} placeholder="Fragrance sensitivity" /><label className="flex items-center gap-3 rounded-xl bg-[#fbf5ed] p-3 text-sm"><input type="checkbox" checked={draft.is_active} onChange={(event) => onChange("is_active", event.target.checked)} className="h-4 w-4 accent-[#70452c]" /><span><strong>{draft.is_active ? "Publish on shop" : "Keep paused"}</strong><span className="ml-2 text-[#897666]">{draft.is_active ? "Customers can see and purchase this product." : "Save it privately until you are ready."}</span></span></label><div className="flex flex-col-reverse gap-3 border-t border-[#eee5dc] pt-5 sm:flex-row sm:justify-end"><Button type="button" onClick={onClose} variant="outline" className="border-[#e1d2c3]">Cancel</Button><Button type="submit" disabled={saving || uploading} className="bg-[#70452c] text-white hover:bg-[#593620]">{saving ? "Saving product…" : editing ? "Save changes" : "Publish product"}</Button></div></div></form></div></div>; }
function Field({ label, value, onChange, type = "text", required, placeholder }: { label: string; value: string; onChange: (value: string) => void; type?: string; required?: boolean; placeholder?: string }) { return <div><Label>{label}</Label><Input type={type} required={required} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="mt-2 h-11 border-[#e6d8ca]" /></div>; }
function TagField({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) { return <div><Label>{label}</Label><Input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="mt-2 h-11 border-[#e6d8ca]" /><p className="mt-1 text-[11px] text-[#a28d7c]">Separate items with commas.</p></div>; }
function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[][] }) { return <div><Label>{label}</Label><select value={value} onChange={(event) => onChange(event.target.value)} className="mt-2 h-11 w-full rounded-md border border-[#e6d8ca] bg-white px-3 text-sm">{options.map(([optionValue, optionLabel]) => <option key={optionValue} value={optionValue}>{optionLabel}</option>)}</select></div>; }
function StatusBadge({ value }: { value: string }) { const normalized = value.toLowerCase(); const positive = ["live", "active", "paid", "completed", "confirmed", "profile complete"].includes(normalized); const warning = ["pending", "processing", "scheduled", "unpaid", "profile to finish"].includes(normalized); return <Badge className={`border-0 text-[10px] font-semibold ${positive ? "bg-[#edf4ec] text-[#57835c]" : warning ? "bg-[#fbf1df] text-[#996b2f]" : "bg-[#f7e8e5] text-[#9b5c4f]"}`}>{value}</Badge>; }
function EmptyState({ icon: Icon, title, text, action }: { icon: typeof Activity; title: string; text: string; action?: ReactNode }) { return <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-[#dbc9b8] bg-[#fdfaf6] px-6 py-14 text-center"><span className="rounded-2xl bg-[#f5ebe0] p-3 text-[#a26b43]"><Icon className="h-6 w-6" /></span><h3 className="mt-5 font-display text-xl">{title}</h3><p className="mt-2 max-w-md text-sm leading-6 text-[#897666]">{text}</p>{action ? <div className="mt-5">{action}</div> : null}</div>; }
function ShieldIcon() { return <span className="text-lg">✦</span>; }
